import pandas as pd
import numpy as np
import re
import os

# Load data
train = pd.read_csv("./input/en_train.csv")
test = pd.read_csv("./input/en_test_2.csv")
sample_sub = pd.read_csv("./input/en_sample_submission_2.csv")

# Precompute efficient lookup: before_str -> most common after_str (from full training set)
before_to_after = {}
for _, row in train.iterrows():
    before = str(row["before"]).strip()
    after = str(row["after"]).strip()
    key = before
    if key not in before_to_after:
        before_to_after[key] = []
    before_to_after[key].append(after)

# Collapse to mode (first most frequent; ties broken by first occurrence)
before_to_after_mode = {}
for key, afters in before_to_after.items():
    if len(afters) == 1:
        before_to_after_mode[key] = afters[0]
    else:
        counts = {}
        for a in afters:
            counts[a] = counts.get(a, 0) + 1
        max_count = max(counts.values())
        for a in afters:
            if counts[a] == max_count:
                before_to_after_mode[key] = a
                break


# Helper functions
def num_to_words_small(n):
    ones = [
        "zero",
        "one",
        "two",
        "three",
        "four",
        "five",
        "six",
        "seven",
        "eight",
        "nine",
        "ten",
        "eleven",
        "twelve",
        "thirteen",
        "fourteen",
        "fifteen",
        "sixteen",
        "seventeen",
        "eighteen",
        "nineteen",
    ]
    tens = [
        "",
        "",
        "twenty",
        "thirty",
        "forty",
        "fifty",
        "sixty",
        "seventy",
        "eighty",
        "ninety",
    ]
    if n < 20:
        return ones[n]
    elif n < 100:
        res = tens[n // 10]
        if n % 10 > 0:
            res += " " + ones[n % 10]
        return res
    return str(n)


def num_to_words_thousands(n):
    if n < 100:
        return num_to_words_small(n)
    elif n < 1000:
        hundreds = n // 100
        remainder = n % 100
        result = [
            "zero",
            "one",
            "two",
            "three",
            "four",
            "five",
            "six",
            "seven",
            "eight",
            "nine",
        ][hundreds] + " hundred"
        if remainder > 0:
            result += " " + num_to_words_small(remainder)
        return result
    else:
        thousands = n // 1000
        remainder = n % 1000
        result = [
            "zero",
            "one",
            "two",
            "three",
            "four",
            "five",
            "six",
            "seven",
            "eight",
            "nine",
        ][thousands] + " thousand"
        if remainder > 0:
            if remainder < 100:
                result += " " + num_to_words_small(remainder)
            else:
                result += " " + num_to_words_thousands(remainder)
        return result


def month_to_word(m):
    months = [
        "january",
        "february",
        "march",
        "april",
        "may",
        "june",
        "july",
        "august",
        "september",
        "october",
        "november",
        "december",
    ]
    return months[m - 1] if 1 <= m <= 12 else str(m)


def day_to_word(d):
    if d == 1:
        return "first"
    elif d == 2:
        return "second"
    elif d == 3:
        return "third"
    elif d == 20:
        return "twentieth"
    elif d == 30:
        return "thirtieth"
    elif d < 20:
        return num_to_words_small(d)
    else:
        tens = ["", "", "twenty", "thirty"][d // 10]
        ones = d % 10
        return tens + ("-" + num_to_words_small(ones) if ones > 0 else "")


def year_to_words(y):
    if y < 1000:
        return num_to_words_thousands(y)
    elif y < 2000:
        hundreds = y // 100
        remainder = y % 100
        if remainder == 0:
            return num_to_words_small(hundreds) + " hundred"
        elif remainder < 10:
            return num_to_words_small(hundreds) + " oh " + num_to_words_small(remainder)
        else:
            return num_to_words_small(hundreds) + " " + num_to_words_small(remainder)
    else:
        thousands = y // 1000
        remainder = y % 1000
        if remainder == 0:
            return num_to_words_small(thousands) + " thousand"
        elif remainder < 100:
            return (
                num_to_words_small(thousands) + " oh " + num_to_words_small(remainder)
            )
        else:
            return (
                num_to_words_small(thousands) + " " + num_to_words_thousands(remainder)
            )


def normalize_decimal(before):
    # Handle cases like ".5" (no leading zero) and "3.04" (with leading zeros)
    decimal_match = re.match(r"^-?\.?(\d*)\.(\d+)$", before)
    if decimal_match:
        int_part = decimal_match.group(1)
        dec_part = decimal_match.group(2)
        try:
            result = ""
            # Handle negative sign
            if before.startswith("-"):
                result = "minus "
            # Handle integer part (could be empty for .5 cases)
            if int_part == "":
                result += "point"
            else:
                int_val = int(int_part) if int_part else 0
                if int_val == 0:
                    result += "zero"
                else:
                    result += num_to_words_thousands(int_val)
                result += " point"
            # Handle decimal part - preserve all digits including leading zeros
            for digit in dec_part:
                result += " " + num_to_words_small(int(digit))
            return result
        except:
            pass
    return None


def normalize_ordinal(before):
    ordinal_match = re.match(r"^(\d+)(st|nd|rd|th)$", before, re.IGNORECASE)
    if ordinal_match:
        num_str = ordinal_match.group(1)
        suffix = ordinal_match.group(2).lower()
        try:
            num = int(num_str)
            if num == 1:
                return "first"
            elif num == 2:
                return "second"
            elif num == 3:
                return "third"
            elif num == 20:
                return "twentieth"
            elif num == 21:
                return "twenty-first"
            elif num == 22:
                return "twenty-second"
            elif num == 23:
                return "twenty-third"
            elif num == 30:
                return "thirtieth"
            elif num == 40:
                return "fortieth"
            elif num == 50:
                return "fiftieth"
            elif num == 60:
                return "sixtieth"
            elif num == 70:
                return "seventieth"
            elif num == 80:
                return "eightieth"
            elif num == 90:
                return "ninetieth"
            elif num == 100:
                return "hundredth"
            elif num == 1000:
                return "thousandth"
            if num < 20:
                return num_to_words_small(num) + "th"
            elif num < 100:
                tens = num // 10
                ones = num % 10
                if ones == 0:
                    return num_to_words_small(num) + "th"
                elif ones == 1:
                    return num_to_words_small(num - 1) + "first"
                elif ones == 2:
                    return num_to_words_small(num - 2) + "second"
                elif ones == 3:
                    return num_to_words_small(num - 3) + "third"
                else:
                    return num_to_words_small(num) + "th"
            else:
                words = num_to_words_thousands(num)
                # For numbers >= 1000, append appropriate ordinal suffix
                last_two = num % 100
                if last_two == 1:
                    return words + " first"
                elif last_two == 2:
                    return words + " second"
                elif last_two == 3:
                    return words + " third"
                else:
                    return words + " th"
        except:
            pass
    return None


def normalize_text(before_val):
    before = str(before_val).strip()
    if before == "" or before == "nan":
        return "missing"
    if before in before_to_after_mode:
        return before_to_after_mode[before]
    if before in {
        ".",
        "?",
        "!",
        ",",
        '"',
        "-",
        ":",
        ";",
        "'",
        "(",
        ")",
        "[",
        "]",
        "{",
        "}",
    }:
        return before if before != "." else "sil"
    ordinal_result = normalize_ordinal(before)
    if ordinal_result is not None:
        return ordinal_result
    decimal_result = normalize_decimal(before)
    if decimal_result is not None:
        return decimal_result
    if before.isdigit() or (before.startswith("-") and before[1:].isdigit()):
        try:
            num = int(before)
            if num < 0:
                return "minus " + normalize_text(str(-num))
            elif num < 100:
                return num_to_words_small(num)
            elif num < 10000:
                return num_to_words_thousands(num)
            else:
                return before
        except:
            pass
    date_match = re.match(r"^(\d{1,2})/(\d{1,2})/(\d{4})$", before)
    if date_match:
        month, day, year = map(int, date_match.groups())
        return f"{month_to_word(month)} {day_to_word(day)}, {year_to_words(year)}"
    curr_match = re.match(r"^\$(\d+)(?:\.(\d{2}))?$", before)
    if curr_match:
        dollars = int(curr_match.group(1))
        cents = curr_match.group(2)
        result = num_to_words_small(dollars) + " dollar" + ("s" if dollars != 1 else "")
        if cents and int(cents) > 0:
            result += (
                ", "
                + num_to_words_small(int(cents))
                + " cent"
                + ("s" if int(cents) != 1 else "")
            )
        return result
    time_match = re.match(r"^(\d{1,2}):(\d{2})$", before)
    if time_match:
        hour, minute = map(int, time_match.groups())
        if minute == 0:
            return f"{num_to_words_small(hour)} o'clock"
        elif minute < 10:
            return f"{num_to_words_small(hour)} oh {num_to_words_small(minute)}"
        else:
            return f"{num_to_words_small(hour)} {num_to_words_small(minute)}"
    if before.isalpha() and before.isupper():
        return " ".join(list(before.lower()))
    return before


def validate_row(before_val, actual_val):
    before = str(before_val).strip()
    actual = str(actual_val).strip()
    if before in before_to_after_mode:
        pred = before_to_after_mode[before]
    else:
        pred = normalize_text(before)
    return pred == actual


# Prepare hold-out validation (10% of train) - using different seed for variety
np.random.seed(12345)
val_size = int(len(train) * 0.1)
val_indices = np.random.choice(train.index, val_size, replace=False)
val_df = train.loc[val_indices].copy()

# Compute validation accuracy using full training set lookup
correct = sum(validate_row(row["before"], row["after"]) for _, row in val_df.iterrows())
accuracy = correct / len(val_df)
print(f"Validation Accuracy: {accuracy:.6f}")

# Generate predictions for test set
test["after"] = test["before"].apply(normalize_text)

# Create 'id' column by combining sentence_id and token_id
test["id"] = test["sentence_id"].astype(str) + "_" + test["token_id"].astype(str)

# Create submission with correct columns: id, after
os.makedirs("./submission", exist_ok=True)
submission = test[["id", "after"]].copy()
submission.to_csv("./submission/submission.csv", index=False)

print("Submission saved to ./submission/submission.csv")
